precision highp float;
uniform float time;
uniform vec2 resolution;

float metaball(vec2 p, vec2 c, float r) {
  float d = length(p - c);
  return r * r / (d * d + 0.0001);
}

// Noise function for extra visual complexity
float noise(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// Smooth noise
float smoothNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);

  float a = noise(i);
  float b = noise(i + vec2(1.0, 0.0));
  float c = noise(i + vec2(0.0, 1.0));
  float d = noise(i + vec2(1.0, 1.0));

  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * resolution.xy) / resolution.y;
  float t = time * 1.200;
  float field = 0.0;


  {
    float baseAngle0 = t * (0.8 + 0.0 * 0.15) + 0.000000;
    float phase0 = sin(t * (0.4 + 0.0 * 0.12)) * 0.300;
    float turbPhase0 = sin(t * (1.2 + 0.0 * 0.3)) * 0.200;

    // Complex orbital motion with turbulence
    float angle0 = baseAngle0 + phase0 + turbPhase0;
    float orbitRadius0 = 0.800 * (1.0 + 0.3 * sin(t * (0.6 + 0.0 * 0.1)));

    vec2 c0 = vec2(
      sin(angle0) * orbitRadius0 + sin(t * (2.0 + 0.0 * 0.2)) * 0.1,
      cos(angle0 * 0.9) * 0.500 + cos(t * (1.5 + 0.0 * 0.15)) * 0.08
    );

    // Dynamic radius with pulsing
    float dynamicRadius0 = 0.200 * (1.0 + 0.4 * sin(t * (3.0 + 0.0 * 0.5)));

    field += metaball(uv, c0, dynamicRadius0);
  }

  {
    float baseAngle1 = t * (0.8 + 1.0 * 0.15) + 1.256637;
    float phase1 = sin(t * (0.4 + 1.0 * 0.12)) * 0.300;
    float turbPhase1 = sin(t * (1.2 + 1.0 * 0.3)) * 0.200;

    // Complex orbital motion with turbulence
    float angle1 = baseAngle1 + phase1 + turbPhase1;
    float orbitRadius1 = 0.800 * (1.0 + 0.3 * sin(t * (0.6 + 1.0 * 0.1)));

    vec2 c1 = vec2(
      sin(angle1) * orbitRadius1 + sin(t * (2.0 + 1.0 * 0.2)) * 0.1,
      cos(angle1 * 0.9) * 0.500 + cos(t * (1.5 + 1.0 * 0.15)) * 0.08
    );

    // Dynamic radius with pulsing
    float dynamicRadius1 = 0.200 * (1.0 + 0.4 * sin(t * (3.0 + 1.0 * 0.5)));

    field += metaball(uv, c1, dynamicRadius1);
  }

  {
    float baseAngle2 = t * (0.8 + 2.0 * 0.15) + 2.513274;
    float phase2 = sin(t * (0.4 + 2.0 * 0.12)) * 0.300;
    float turbPhase2 = sin(t * (1.2 + 2.0 * 0.3)) * 0.200;

    // Complex orbital motion with turbulence
    float angle2 = baseAngle2 + phase2 + turbPhase2;
    float orbitRadius2 = 0.800 * (1.0 + 0.3 * sin(t * (0.6 + 2.0 * 0.1)));

    vec2 c2 = vec2(
      sin(angle2) * orbitRadius2 + sin(t * (2.0 + 2.0 * 0.2)) * 0.1,
      cos(angle2 * 0.9) * 0.500 + cos(t * (1.5 + 2.0 * 0.15)) * 0.08
    );

    // Dynamic radius with pulsing
    float dynamicRadius2 = 0.200 * (1.0 + 0.4 * sin(t * (3.0 + 2.0 * 0.5)));

    field += metaball(uv, c2, dynamicRadius2);
  }

  {
    float baseAngle3 = t * (0.8 + 3.0 * 0.15) + 3.769911;
    float phase3 = sin(t * (0.4 + 3.0 * 0.12)) * 0.300;
    float turbPhase3 = sin(t * (1.2 + 3.0 * 0.3)) * 0.200;

    // Complex orbital motion with turbulence
    float angle3 = baseAngle3 + phase3 + turbPhase3;
    float orbitRadius3 = 0.800 * (1.0 + 0.3 * sin(t * (0.6 + 3.0 * 0.1)));

    vec2 c3 = vec2(
      sin(angle3) * orbitRadius3 + sin(t * (2.0 + 3.0 * 0.2)) * 0.1,
      cos(angle3 * 0.9) * 0.500 + cos(t * (1.5 + 3.0 * 0.15)) * 0.08
    );

    // Dynamic radius with pulsing
    float dynamicRadius3 = 0.200 * (1.0 + 0.4 * sin(t * (3.0 + 3.0 * 0.5)));

    field += metaball(uv, c3, dynamicRadius3);
  }

  {
    float baseAngle4 = t * (0.8 + 4.0 * 0.15) + 5.026548;
    float phase4 = sin(t * (0.4 + 4.0 * 0.12)) * 0.300;
    float turbPhase4 = sin(t * (1.2 + 4.0 * 0.3)) * 0.200;

    // Complex orbital motion with turbulence
    float angle4 = baseAngle4 + phase4 + turbPhase4;
    float orbitRadius4 = 0.800 * (1.0 + 0.3 * sin(t * (0.6 + 4.0 * 0.1)));

    vec2 c4 = vec2(
      sin(angle4) * orbitRadius4 + sin(t * (2.0 + 4.0 * 0.2)) * 0.1,
      cos(angle4 * 0.9) * 0.500 + cos(t * (1.5 + 4.0 * 0.15)) * 0.08
    );

    // Dynamic radius with pulsing
    float dynamicRadius4 = 0.200 * (1.0 + 0.4 * sin(t * (3.0 + 4.0 * 0.5)));

    field += metaball(uv, c4, dynamicRadius4);
  }




  // Enhanced color mixing with dynamic shifts
  float colorTime = t * 0.500;
  float noiseValue = smoothNoise(uv * 3.0 + t * 0.5) * 0.3;

  // Multiple threshold levels for richer visuals
  float threshold1 = smoothstep(0.8, 1.4, field + noiseValue);
  float threshold2 = smoothstep(1.2, 1.8, field);
  float threshold3 = smoothstep(1.6, 2.2, field);
  float edge = smoothstep(0.6, 1.0, field) - threshold1;

  // Dynamic color palette
  vec3 startColor = vec3(0.0, 0.028, 0.25);
  vec3 midColor = vec3(
    0.2 + 0.3 * sin(colorTime * 0.7),
    0.1 + 0.4 * sin(colorTime * 0.9 + 2.0),
    0.6 + 0.3 * sin(colorTime * 1.1 + 4.0)
  );
  vec3 endColor = vec3(
      0.1 + 0.4 * sin(colorTime + 1.0),
      0.3 + 0.5 * sin(colorTime * 1.3 + 3.0),
      0.8 + 0.2 * sin(colorTime * 0.8 + 5.0)
    );

  // Multi-layer color blending
  vec3 color = mix(startColor, midColor, threshold1);
  color = mix(color, endColor, threshold2);
  color += threshold3 * vec3(1.0, 0.8, 0.6) * 0.5;

  // Enhanced glow with multiple layers
  color += edge * midColor * 2.00;
  color += threshold1 * 0.1 * vec3(1.0, 0.9, 0.7);

  // Animated brightness modulation
  float brightness = 0.85 + 0.15 * sin(time * 2.5) + 0.1 * sin(time * 4.7);
  color *= brightness;

  // Subtle vignette effect
  float vignette = 1.0 - 0.3 * length(uv);
  color *= vignette;

  gl_FragColor = vec4(color, 1.0);
}

